/**
 * The contract `spinner.tsx` (native) and `spinner.web.tsx` (web) both implement.
 * Its own module because Metro resolves `./spinner` to `spinner.web.tsx` on web.
 */

export type SpinnerProps = {
  /**
   * The spinner's accessible name, announced by its `role="status"`. Say what is
   * loading when the screen has more than one thing that could be.
   */
  label?: string | undefined;
  /** Size and colour: `size-6`, `text-muted-foreground`. The default is `size-4`. */
  className?: string | undefined;
};

/** The glyph's size when the call site names none, shadcn's. */
export const spinnerClass = "size-4";

/** One turn, in ms: Tailwind's `animate-spin`, which the web half uses. */
export const SPIN_DURATION = 1000;

/**
 * A loading indicator: the `LoaderCircle` glyph, turning. `spinner.web.tsx` is
 * the web counterpart and `spinner-base.ts` holds what they share.
 *
 * Not `ActivityIndicator`. That one draws the platform's own spinner, which is
 * a different shape on iOS, on Android and in the browser, and takes a colour
 * prop but no class. This is the same glyph the web half turns, sized and
 * coloured by `className` through `@cubeui/icons` — so inside a `Button` it
 * takes the button's ink from `IconClassContext`, as any icon there does.
 *
 * The turn is `Animated` on the native driver, one linear turn a second, which
 * is Tailwind's `animate-spin`. The compiler refuses `Animated`, which is why
 * the web half is hand-written rather than compiled from this file.
 */
import { useEffect, useRef } from "react";
import { Animated, Easing } from "react-native";
import { LoaderCircle } from "@/components/ui/icons";
import { SPIN_DURATION, type SpinnerProps, spinnerClass } from "@/components/ui/spinner-base";
import { cn } from "@/lib/utils";

export type { SpinnerProps };

export function Spinner({ label = "Loading", className }: SpinnerProps) {
  const turn = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    const loop = Animated.loop(
      Animated.timing(turn, {
        toValue: 1,
        duration: SPIN_DURATION,
        easing: Easing.linear,
        useNativeDriver: true,
      }),
    );
    loop.start();
    return () => loop.stop();
  }, [turn]);

  const rotate = turn.interpolate({ inputRange: [0, 1], outputRange: ["0deg", "360deg"] });

  return (
    <Animated.View
      role="status"
      aria-label={label}
      style={{ alignSelf: "flex-start", transform: [{ rotate }] }}
    >
      <LoaderCircle className={cn(spinnerClass, className)} aria-hidden />
    </Animated.View>
  );
}

/**
 * The web spinner: shadcn's — `LoaderCircle` with `animate-spin`, a
 * `role="status"` named `Loading`. `spinner.tsx` is the native counterpart and
 * its header says why it is not `ActivityIndicator`; `spinner-base.ts` holds
 * what they share.
 *
 * It takes `label` and `className` and nothing else, as the native half does:
 * shadcn's spreads the rest of the `<svg>`'s attributes, and a call site that
 * passed one is rare enough to wrap the glyph itself.
 *
 * The glyph is `currentColor`, so it takes the colour of the text around it —
 * a button's label, a muted line — unless `className` names one.
 */
import { LoaderCircle } from "@/components/ui/icons";
import { type SpinnerProps, spinnerClass } from "@/components/ui/spinner-base";
import { cn } from "@/lib/utils";

export type { SpinnerProps };

export function Spinner({ label = "Loading", className }: SpinnerProps) {
  return (
    <LoaderCircle
      data-slot="spinner"
      role="status"
      aria-label={label}
      className={cn(spinnerClass, "animate-spin", className)}
    />
  );
}
